SELECT m.user_id AS userId, m.name AS name, m.email AS email, m.role AS role, m.deleted AS deleted, m.created_at AS createdAt FROM member m WHERE m.deleted = 1 AND m.role = 'role_user'
AND ( m.user_id LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') OR m.email LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY m.created_at DESC LIMIT #{size} OFFSET #{offset}

